package com.coworkhub.service;
import com.coworkhub.entity.*;import com.coworkhub.repository.*;import org.springframework.stereotype.Service;import java.util.List;
@Service public class CatalogBusinessServiceImpl implements CatalogBusinessService {private final LocationRepository locations;private final RoomRepository rooms;private final EquipmentRepository equipment;private final MembershipPlanRepository plans;private final AdditionalServiceRepository services;public CatalogBusinessServiceImpl(LocationRepository l,RoomRepository r,EquipmentRepository e,MembershipPlanRepository p,AdditionalServiceRepository s){locations=l;rooms=r;equipment=e;plans=p;services=s;}public List<Location> locations(){return locations.findAll();}public List<Room> rooms(){return rooms.findAllWithDetails();}public List<Equipment> equipment(){return equipment.findAll();}public List<MembershipPlan> plans(){return plans.findAll();}public List<AdditionalService> additionalServices(){return services.findAll();}}
